private void addEmail(){
  currentEmail=Helper.getValue(inputEmail.getText());
  if (Helper.isNullOrEmpty(currentEmail) || currentEmail.indexOf("@") == -1) {
    Snackbar.make(getView(),R.string.provide_valid_email,Snackbar.LENGTH_LONG).setBackgroundTint(Color.RED).setTextColor(Color.WHITE).show();
    return;
  }
  Context context=getContext();
  if (context != null) {
    InputMethodManager imm=(InputMethodManager)context.getSystemService(Activity.INPUT_METHOD_SERVICE);
    imm.hideSoftInputFromWindow(inputEmail.getWindowToken(),0);
  }
  EmailNewTask task=new EmailNewTask(currentEmail,emailAddProgress,new EmailNewTask.EmailNewHandler(){
    @Override public void beforeStart(){
      Helper.setViewVisibility(buttonContinue,View.INVISIBLE);
    }
    @Override public void onSuccess(){
      layoutCollect.setVisibility(View.GONE);
      layoutVerify.setVisibility(View.VISIBLE);
      Helper.setViewText(textAddedEmail,currentEmail);
      if (listener != null) {
        listener.onEmailAdded(currentEmail);
      }
      try {
        scheduleEmailVerify();
      } catch (RejectedExecutionException | SecurityException e) {
        Snackbar.make(getView(), "Failed to schedule email verification: " + e.getMessage(), Snackbar.LENGTH_LONG).setBackgroundTint(Color.RED).setTextColor(Color.WHITE).show();
      }
      Helper.setViewVisibility(buttonContinue,View.VISIBLE);
    }
    @Override public void onEmailExists(){
    }
    @Override public void onError(Exception error){
      Snackbar.make(getView(),error.getMessage(),Snackbar.LENGTH_LONG).setBackgroundTint(Color.RED).setTextColor(Color.WHITE).show();
      Helper.setViewVisibility(buttonContinue,View.VISIBLE);
    }
  }
);
  task.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
}
